struct TypeEnv<'a> {
    scopes: Vec<HashMap<String, ResolvedType>>,
    types: HashMap<String, ResolvedType>,
    span_mapper: &'a SpanMapper,
    filename: &'a str,
}

impl<'a> TypeEnv<'a> {
    fn new(span_mapper: &'a SpanMapper, filename: &'a str) -> Self {
        let mut env = Self {
            scopes: vec![HashMap::new()],
            types: HashMap::new(),
            span_mapper,
            filename,
        };
        env.types.insert("Int".into(), ResolvedType::Int(IntSize::I64));
        env.types.insert("UInt".into(), ResolvedType::Int(IntSize::U64));
        env.types.insert("Float".into(), ResolvedType::Float(FloatSize::F64));
        env.types.insert("Bool".into(), ResolvedType::Bool);
        env.types.insert("Char".into(), ResolvedType::Char);
        env.types.insert("String".into(), ResolvedType::String);
        env
    }

    fn push_scope(&mut self) { self.scopes.push(HashMap::new()); }
    fn pop_scope(&mut self) { self.scopes.pop(); }

    fn define(&mut self, name: String, ty: ResolvedType) {
        if let Some(scope) = self.scopes.last_mut() {
            scope.insert(name, ty);
        }
    }

    fn lookup(&self, name: &str) -> Option<&ResolvedType> {
        for scope in self.scopes.iter().rev() {
            if let Some(ty) = scope.get(name) {
                return Some(ty);
            }
        }
        self.types.get(name)
    }

    fn type_error(&self, message: impl Into<String>, span: Span) -> KainError {
        let loc = self.span_mapper.span_to_location(span, self.filename);
        KainError::type_error(format!("{}:{}:{}: {}", loc.file, loc.line, loc.col, message.into()), span)
    }
}

