impl LayoutRegistry {
    fn build_with_abi(items: &[TypedItem], abi: &CAbiPolicy) -> LayoutRegistry {
        let mut registry = LayoutRegistry { abi: abi.clone(), structs: std::collections::HashMap::new() };
        for item in items {
            if let TypedItem::Struct(st) = item {
                let is_union = has_attr(&st.ast.attributes, C_UNION_ATTR);
                let mut fields = std::collections::HashMap::new();
                let mut field_order = Vec::new();
                let mut offset: usize = 0;
                let mut max_align: usize = 1;
                let mut max_field_size: usize = 1;
                for field in &st.ast.fields {
                    let field_size = attr_usize_arg(&field.attributes, C_STORAGE_BITS_ATTR).unwrap_or(1).max(1);
                    let field_align = attr_usize_arg(&field.attributes, C_STORAGE_ALIGN_ATTR).unwrap_or(1).max(1);
                    max_align = max_align.max(field_align);
                    max_field_size = max_field_size.max(field_size);
                    if !is_union {
                        offset = align_up(offset, field_align);
                    }
                    let field_offset = if is_union { 0 } else { offset };
                    fields.insert(field.name.clone(), LayoutField {
                        offset: field_offset,
                        ty: field.ty.clone(),
                        bit_width: None,
                        bit_offset: None,
                        bit_signed: false,
                    });
                    field_order.push(field.name.clone());
                    if !is_union {
                        offset += field_size;
                    }
                }
                let size = if is_union { max_field_size } else { align_up(offset.max(1), max_align) };
                registry.structs.insert(st.ast.name.clone(), StructLayoutInfo {
                    size,
                    align: max_align,
                    is_union,
                    field_order,
                    fields,
                });
            }
        }
        registry
    }
}

impl LayoutRegistry {
    fn field(&self, struct_name: &String, field: &String) -> Option<LayoutField> {
        self.structs.get(struct_name).and_then(|info| info.fields.get(field)).cloned()
    }
}

impl LayoutRegistry {
    fn type_size_fallback(&self, ty: &Type) -> usize {
        match ty {
            Type::Named { name, .. } => match name.as_str() {
                "Bool" => self.abi.bool_bits.div_ceil(8),
                "Char" => self.abi.char_bits.div_ceil(8),
                "Int" | "isize" | "usize" => self.abi.long_bits.div_ceil(8),
                "Float" => self.abi.double_bits.div_ceil(8),
                other => self.structs.get(other).map(|info| info.size).unwrap_or(8),
            },
            Type::Array(inner, size, _) => self.type_size_fallback(inner) * *size,
            Type::Slice(_, _) => 16,
            Type::Tuple(_, _) => 8,
            Type::Ref { .. } | Type::Ptr { .. } => 8,
            Type::Option(inner, _) => self.type_size_fallback(inner),
            Type::Result(ok, err, _) => self.type_size_fallback(ok).max(self.type_size_fallback(err)),
            Type::Unit(_) => 0,
            Type::Never(_) => 0,
            _ => 8,
        }
    }
}

