    }
}

fn lower_storage_expr(ty: &Type, layouts: &LayoutRegistry, span: Span, zeroed: bool) -> Expr {
    match ty {
        Type::Array(inner, count, _) => Expr::Array(
            (0..*count)
                .map(|_| lower_storage_expr(inner, layouts, span.clone(), zeroed))
                .collect(),
            span,
        ),
        Type::Tuple(items, _) => Expr::Tuple(
            items
                .iter()
                .map(|item| lower_storage_expr(item, layouts, span.clone(), zeroed))
                .collect(),
            span,
        ),
        Type::Named { name, .. } => match name.as_str() {
            "Int" | "UInt" | "isize" | "usize" => {
                if zeroed { Expr::Int(0, span) } else { Expr::None(span) }
            }
            "Float" => {
                if zeroed { Expr::Float(0.0, span) } else { Expr::None(span) }
            }
            "Bool" => {
                if zeroed { Expr::Bool(false, span) } else { Expr::None(span) }
            }
            "Char" => {
                if zeroed { Expr::String("\0".to_string(), span) } else { Expr::None(span) }
            }
            _ => {
                if let Some(info) = layouts.structs.get(name) {
                    let fields = info
                        .field_order
                        .iter()
                        .filter_map(|field_name| {
                            info.fields.get(field_name).map(|layout| {
                                (
                                    field_name.clone(),
                                    Box::new(lower_storage_expr(&layout.ty, layouts, span.clone(), zeroed)),
                                )
                            })
                        })
                        .collect();
                    Expr::Struct {
                        name: name.clone(),
                        fields,
                        span,
                    }
                } else {
                    Expr::None(span)
                }
            }
        },
        Type::Unit(_) => Expr::Tuple(Vec::new(), span),
        Type::Ref { .. } | Type::Ptr { .. } => Expr::None(span),
        _ => Expr::None(span),
    }
}

fn storage_seed_expr(ty: Option<&Type>, layouts: &LayoutRegistry, span: Span, zeroed: bool) -> Expr {
    ty.map(|ty| lower_storage_expr(ty, layouts, span.clone(), zeroed))
        .unwrap_or_else(|| Expr::None(span))
}

fn lower_heap_alloc_expr(size: &Expr, ty: Option<&Type>, zeroed: bool, layouts: &LayoutRegistry, span: Span) -> Expr {
    helper_call("__kain_alloc".to_string(), vec![size.clone(), Expr::Int(memory_stride_for_type(ty, layouts).unwrap_or(1), span.clone()), Expr::Bool(zeroed, span.clone()), storage_seed_expr(ty, layouts, span.clone(), zeroed)], span)
}

fn lower_aggregate_init_expr(ty: &Type, fields: &[(String, Expr)], zero_fill_rest: bool, layouts: &LayoutRegistry, span: Span) -> Expr {
    match ty {
        Type::Named { name, .. } if layouts.structs.contains_key(name) => {
            let provided: std::collections::HashMap<String, Expr> = fields.iter().cloned().collect();
            let info = layouts.structs.get(name).cloned().unwrap();
            let field_values = info
                .field_order
                .iter()
                .filter_map(|field_name| {
                    let value = provided.get(field_name).cloned().or_else(|| {
                        info.fields.get(field_name).map(|layout| {
                            if zero_fill_rest {
                                lower_storage_expr(&layout.ty, layouts, span.clone(), true)
                            } else {
                                Expr::None(span.clone())
                            }
                        })
                    })?;
                    Some((field_name.clone(), Box::new(value)))
                })
                .collect();
            Expr::Struct {
                name: name.clone(),
                fields: field_values,
                span,
            }
        }
        _ => Expr::Tuple(fields.iter().map(|(_, expr)| expr.clone()).collect(), span),
    }
}

fn lower_union_aggregate_fields(info: &StructLayoutInfo, original_fields: &[(String, Expr)], provided: &std::collections::HashMap<String, Expr>, layouts: &LayoutRegistry, span: Span, zero_fill_rest: bool) -> (Vec<(String, Expr)>, Option<String>, Expr) {
    let active_name = original_fields
        .iter()
        .rev()
        .find_map(|(name, _)| if info.fields.contains_key(name) { Some(name.clone()) } else { None })
        .or_else(|| info.field_order.first().cloned());
    let active_value = active_name
        .as_ref()
        .and_then(|name| provided.get(name).cloned())
        .or_else(|| {
            active_name.as_ref().and_then(|name| {
                original_fields
                    .iter()
                    .find(|(field_name, _)| field_name == name)
                    .map(|(_, expr)| expr.clone())
            })
        })
        .or_else(|| {
            active_name.as_ref().and_then(|name| {
                info.fields.get(name).map(|layout| {
                    if zero_fill_rest {
                        lower_storage_expr(&layout.ty, layouts, span.clone(), true)
                    } else {
                        Expr::None(span.clone())
                    }
                })
            })
        })
        .unwrap_or_else(|| Expr::None(span.clone()));
    let field_values = active_name
        .as_ref()
        .map(|name| vec![(name.clone(), active_value.clone())])
        .unwrap_or_default();
    (field_values, active_name, active_value)
}

