rules.pattern:
fn align_up(value: usize, align: usize) -> usize {
    let align = align.max(1);
    let remainder = ((((value) as u64) % ((align) as u64)));
    if ((remainder == 0)) { value } else { ((value + (((align - remainder))))) }
}

rules.replacement:
fn align_up(value: usize, align: usize) -> usize {
    let align = align.max(1);
    let remainder = value % align;
    if remainder == 0 { value } else { value + (align - remainder) }
}

#[derive(Debug, Clone, PartialEq)]
struct CAbiPolicyEntry {
    pub kind: CAbiKind,
    pub flavor: CCompilerFlavor,
    pub policy: CAbiPolicy,
}

fn policy_entry(key: String, kind: CAbiKind, flavor: CCompilerFlavor, long_bits: usize) -> CAbiPolicyEntry {
    CAbiPolicyEntry {
        kind,
        flavor,
        policy: CAbiPolicy {
            key,
            kind,
            flavor,
            char_bits: 8,
            bool_bits: 8,
            short_bits: 16,
            int_bits: 32,
            long_bits,
            long_long_bits: 64,
            float_bits: 32,
            double_bits: 64,
            pointer_bits: 64,
            integer_promotion_bits: 32,
            bitfield_lsb_first: true,
            packed_struct_align: 1,
        },
    }
}

static C_ABI_POLICY_TABLE: once_cell::sync::Lazy<Vec<CAbiPolicyEntry>> = once_cell::sync::Lazy::new(|| {
    vec![policy_entry("generic-lp64".to_string(), CAbiKind::GenericLp64, CCompilerFlavor::Generic, 64)]
});

fn c_compiler_flavor_from_str(value: &str) -> Option<CCompilerFlavor> {
    match value.trim().to_ascii_lowercase().as_str() {
        "" => None,
        "generic" | "default" => Some(CCompilerFlavor::Generic),
        "gcc" | "gnu" => Some(CCompilerFlavor::Gcc),
        "clang" | "llvm" => Some(CCompilerFlavor::Clang),
        "msvc" | "cl" | "visualc" => Some(CCompilerFlavor::Msvc),
        _ => None,
    }
}

fn selected_c_compiler_flavor() -> CCompilerFlavor {
    std::env::var(KAIN_C_ABI_FLAVOR_ENV).ok().as_deref().and_then(c_compiler_flavor_from_str).unwrap_or(CCompilerFlavor::Generic)
}

fn c_abi_kind_for_target(target: CompileTarget) -> CAbiKind {
    match target {
        crate::CompileTarget::Ue5 | crate::CompileTarget::Ue5Editor => CAbiKind::GenericLlp64,
        _ => CAbiKind::GenericLp64,
    }
}

fn default_c_abi_policy() -> CAbiPolicy {
    c_abi_policy_for_kind_and_flavor(CAbiKind::GenericLp64, selected_c_compiler_flavor())
}

fn c_abi_policy_for_kind_and_flavor(kind: CAbiKind, flavor: CCompilerFlavor) -> CAbiPolicy {
    C_ABI_POLICY_TABLE
        .iter()
        .find(|entry| entry.kind == kind && entry.flavor == flavor)
        .map(|entry| entry.policy.clone())
        .unwrap_or_else(|| C_ABI_POLICY_TABLE[0].policy.clone())
}

fn c_abi_policy_for_target_and_flavor(target: CompileTarget, flavor: CCompilerFlavor) -> CAbiPolicy {
    c_abi_policy_for_kind_and_flavor(c_abi_kind_for_target(target), flavor)
}

fn c_abi_policy_for_target(target: CompileTarget) -> CAbiPolicy {
    c_abi_policy_for_target_and_flavor(target, selected_c_compiler_flavor())
}

fn promoted_integer_bits(width: usize, _signed: bool, abi: &CAbiPolicy) -> usize {
    width.max(abi.integer_promotion_bits)
}

fn has_attr(attrs: &[Attribute], name: &str) -> bool {
    attrs.iter().any(|attr| attr.name == name)
}

fn attr_usize_arg(attrs: &[Attribute], name: &str) -> Option<usize> {
    attrs.iter().find(|attr| attr.name == name).and_then(|attr| attr.args.first()).and_then(|expr| match expr { Expr::Int(value, _) => Some(*value as usize), _ => None })
}

fn attr_usize_bool_args(attrs: &[Attribute], name: &str) -> Option<(usize, bool)> {
    attrs.iter().find(|attr| attr.name == name).map(|attr| {
        let width = attr.args.first().and_then(|expr| match expr { Expr::Int(value, _) => Some(*value as usize), _ => None }).unwrap_or(0);
        let signed = attr.args.get(1).and_then(|expr| match expr { Expr::Bool(value, _) => Some(*value), _ => None }).unwrap_or(false);
        (width, signed)
    })
}

