fn first_unsupported_memory_context(items: &[TypedItem], caps: BackendMemoryCapabilities) -> Option<String> {
    for item in items {
        match item {
            TypedItem::Function(function) => {
                if let Some(context) = first_unsupported_memory_context_in_function(function, caps) {
                    return Some(context);
                }
            }
            TypedItem::Struct(st) if !caps.raw_pointers => {
                for field in &st.ast.fields {
                    if field.ty.contains_raw_ptr() {
                        return Some(format!("Struct '{}' field '{}' uses a raw pointer type", st.ast.name, field.name));
                    }
                }
            }
            TypedItem::Component(component) if !caps.raw_pointers => {
                for prop in &component.ast.props {
                    if prop.ty.contains_raw_ptr() {
                        return Some(format!("Component '{}' prop '{}' uses a raw pointer type", component.ast.name, prop.name));
                    }
                }
            }
            TypedItem::Actor(actor) if !caps.raw_pointers => {
                for state in &actor.ast.state_ {
                    if state.ty.contains_raw_ptr() {
                        return Some(format!("Actor '{}' state '{}' uses a raw pointer type", actor.ast.name, state.name));
                    }
                }
            }
            TypedItem::Const(const_item) => {
                if !caps.raw_pointers && const_item.ast.ty.contains_raw_ptr() {
                    return Some(format!("Const '{}' uses a raw pointer type", const_item.ast.name));
                }
                if !caps.raw_memory_ops {
                    if let Some(context) = first_memory_expr_context(&const_item.ast.value, format!("Const '{}' contains a raw memory operation", const_item.ast.name)) {
                        return Some(context);
                    }
                }
            }
            TypedItem::TypeAlias(alias) if !caps.raw_pointers => {
                if alias.ast.target.contains_raw_ptr() {
                    return Some(format!("Type alias '{}' uses a raw pointer type", alias.ast.name));
                }
            }
            TypedItem::Impl(imp) => {
                for method in &imp.ast.methods {
                    if let Some(context) = first_unsupported_memory_context_in_ast_function(method, caps) {
                        return Some(format!("Impl method '{}': {}", method.name, context));
                    }
                }
            }
            _ => {}
        }
    }
    None
}

fn first_unsupported_memory_context_in_function(function: &TypedFunction, caps: BackendMemoryCapabilities) -> Option<String> {
    if !caps.raw_pointers {
        for param in &function.ast.params {
            if param.ty.contains_raw_ptr() {
                return Some(format!("Function '{}' parameter '{}' uses a raw pointer type", function.ast.name, param.name));
            }
        }
        if let Some(ret) = &function.ast.return_type {
            if ret.contains_raw_ptr() {
                return Some(format!("Function '{}' return type uses a raw pointer type", function.ast.name));
            }
        }
    }
    if !caps.raw_memory_ops {
        return first_memory_block_context(&function.ast.body, format!("Function '{}'", function.ast.name));
    }
    None
}

fn first_unsupported_memory_context_in_ast_function(function: &Function, caps: BackendMemoryCapabilities) -> Option<String> {
    if !caps.raw_pointers {
        for param in &function.params {
            if param.ty.contains_raw_ptr() {
                return Some(format!("Function '{}' parameter '{}' uses a raw pointer type", function.name, param.name));
            }
        }
        if let Some(ret) = &function.return_type {
            if ret.contains_raw_ptr() {
                return Some(format!("Function '{}' return type uses a raw pointer type", function.name));
            }
        }
    }
    if !caps.raw_memory_ops {
        return first_memory_block_context(&function.body, format!("Function '{}'", function.name));
    }
    None
}

fn first_memory_block_context(block: &Block, owner: String) -> Option<String> {
    for stmt in &block.stmts {
        if let Some(context) = first_memory_stmt_context(stmt, &owner) {
            return Some(context);
        }
    }
    None
}

fn first_memory_stmt_context(stmt: &Stmt, owner: &String) -> Option<String> {
    match stmt {
        Stmt::Expr(expr) => first_memory_expr_context(expr, format!("{} contains a raw memory operation", owner)),
        Stmt::Let { value, .. } => value.as_ref().and_then(|expr| first_memory_expr_context(expr, format!("{} local initializer contains a raw memory operation", owner))),
        Stmt::Return(Some(expr), _) => first_memory_expr_context(expr, format!("{} return contains a raw memory operation", owner)),
        Stmt::For { iter, body, .. } => first_memory_expr_context(iter, format!("{} loop iterator contains a raw memory operation", owner))
            .or_else(|| first_memory_block_context(body, owner.to_string())),
        Stmt::While { condition, body, .. } => first_memory_expr_context(condition, format!("{} loop condition contains a raw memory operation", owner))
            .or_else(|| first_memory_block_context(body, owner.to_string())),
        Stmt::Loop { body, .. } => first_memory_block_context(body, owner.to_string()),
        Stmt::Item(_) | Stmt::Return(None, _) | Stmt::Break(_, _) | Stmt::Continue(_) => None,
    }
}

fn first_memory_expr_context(expr: &Expr, base: String) -> Option<String> {
    match expr {
        Expr::AddrOf { .. } => Some(format!("{}: address-of expression", base)),
        Expr::PtrOffset { .. } => Some(format!("{}: pointer offset expression", base)),
        Expr::MemLoad { .. } => Some(format!("{}: raw memory load expression", base)),
        Expr::MemStore { .. } => Some(format!("{}: raw memory store expression", base)),
        Expr::Alloc { size, .. } => first_memory_expr_context(size, base),
        Expr::Realloc { pointer, size, .. } => first_memory_expr_context(pointer, base.clone()).or_else(|| first_memory_expr_context(size, base)),
        Expr::AggregateInit { fields, .. } => fields.iter().find_map(|(_, expr)| first_memory_expr_context(expr, base.clone())),
        Expr::Binary { left, right, .. } => first_memory_expr_context(left, base.clone()).or_else(|| first_memory_expr_context(right, base)),
        Expr::Unary { operand, .. }
        | Expr::Ref { value: operand, .. }
        | Expr::Cast { value: operand, .. }
        | Expr::Paren(operand, _)
        | Expr::Try(operand, _)
        | Expr::Await(operand, _)
        | Expr::Comptime(operand, _)
        | Expr::Deref(operand, _) => first_memory_expr_context(operand, base),
        Expr::Call { callee, args, .. } => first_memory_expr_context(callee, base.clone())
            .or_else(|| args.iter().find_map(|arg| first_memory_expr_context(&arg.value, base.clone()))),
        Expr::MethodCall { receiver, args, .. } => first_memory_expr_context(receiver, base.clone())
            .or_else(|| args.iter().find_map(|arg| first_memory_expr_context(&arg.value, base.clone()))),
        Expr::Field { object, .. } => first_memory_expr_context(object, base),
        Expr::Index { object, index, .. } => first_memory_expr_context(object, base.clone()).or_else(|| first_memory_expr_context(index, base)),
        Expr::Assign { target, value, .. } => first_memory_expr_context(target, base.clone()).or_else(|| first_memory_expr_context(value, base)),
        Expr::Struct { fields, .. } => fields.iter().find_map(|(_, expr)| first_memory_expr_context(expr, base.clone())),
        Expr::EnumVariant { fields, .. } => match fields {
            EnumVariantFields::Unit => None,
            EnumVariantFields::Tuple(items) => items.iter().find_map(|expr| first_memory_expr_context(expr, base.clone())),
            EnumVariantFields::Struct(items) => items.iter().find_map(|(_, expr)| first_memory_expr_context(expr, base.clone())),
        },
        Expr::Array(items, _) | Expr::Tuple(items, _) | Expr::FString(items, _) => items.iter().find_map(|expr| first_memory_expr_context(expr, base.clone())),
        Expr::Range { start, end, .. } => start.as_deref().and_then(|expr| first_memory_expr_context(expr, base.clone())).or_else(|| end.as_deref().and_then(|expr| first_memory_expr_context(expr, base))),
        Expr::If { condition, then_branch, else_branch, .. } => first_memory_expr_context(condition, base.clone())
            .or_else(|| first_memory_block_context(then_branch, base.clone()))
            .or_else(|| else_branch.as_deref().and_then(|branch| match branch { ElseBranch::Else(block) => first_memory_block_context(block, base.clone()), ElseBranch::ElseIf(expr, ..) => first_memory_expr_context(expr, base.clone()) })),
        Expr::Match { scrutinee, arms, .. } => first_memory_expr_context(scrutinee, base.clone())
            .or_else(|| arms.iter().find_map(|arm| first_memory_expr_context(&arm.body, base.clone()))),
        Expr::Lambda { body, .. } => first_memory_expr_context(body, base),
        Expr::Spawn { init, .. } | Expr::SendMsg { data: init, .. } => init.iter().find_map(|(_, expr)| first_memory_expr_context(expr, base.clone())),
        Expr::Block(block, _) => first_memory_block_context(block, base),
        Expr::MacroCall { args, .. } => args.iter().find_map(|expr| first_memory_expr_context(expr, base.clone())),
        Expr::Return(Some(expr), _) | Expr::Break(Some(expr), _) => first_memory_expr_context(expr, base),
        Expr::SizeOfType { .. }
        | Expr::AlignOfType { .. }
        | Expr::Alloca { .. }
        | Expr::Uninit { .. }
        | Expr::Int(_, _)
        | Expr::Float(_, _)
        | Expr::String(_, _)
        | Expr::Bool(_, _)
        | Expr::None(_)
        | Expr::Ident(_, _)
        | Expr::Return(None, _)
        | Expr::Break(None, _)
        | Expr::Continue(_)
        | Expr::JSX(_, _) => None,
    }
}

#[derive(Debug, Clone)]
struct MonomorphizedProgram {
    pub items: Vec<TypedItem>,
}

fn monomorphize(program: &TypedProgram) -> Result<MonomorphizedProgram, KainError> {
    Ok(MonomorphizedProgram { items: program.items.clone() })
}

impl MonoContext {
    fn instantiate(&mut self, name: &String, type_args: &[ResolvedType]) -> Result<String, KainError> {
        let mangled_name = format!("{}_{}", name, mangle_types(type_args));
        self.instantiated.insert(mangled_name.clone(), mangled_name.clone());
        Ok(mangled_name)
    }
}

impl MonoContext {
    fn instantiate_struct(&mut self, name: &String, type_args: &[ResolvedType]) -> Result<String, KainError> {
        let mangled_name = format!("{}_{}", name, mangle_types(type_args));
        self.instantiated_structs.insert(mangled_name.clone(), mangled_name.clone());
        Ok(mangled_name)
    }
}

impl MonoContext {
    fn instantiate_impl_methods(&mut self, _instantiated_struct_name: &String, _generic_impl: &TypedImpl, _type_args: &[ResolvedType]) -> Result<(), KainError> {
        Ok(())
    }
}

fn mangle_types(types: &[ResolvedType]) -> String {
    types.iter().map(type_to_string).collect::<Vec<_>>().join("_")
}

fn unify(param_type: &ResolvedType, arg_type: &ResolvedType, bindings: &mut std::collections::HashMap<String, ResolvedType>) {
    match param_type {
        ResolvedType::Generic(name) => {
            bindings.entry(name.clone()).or_insert_with(|| arg_type.clone());
        }
        ResolvedType::Function { params, ret, .. } => {
            if let ResolvedType::Function { params: arg_params, ret: arg_ret, .. } = arg_type {
                for (param, arg) in params.iter().zip(arg_params.iter()) {
                    unify(param, arg, bindings);
                }
                unify(ret, arg_ret, bindings);
            }
        }
        ResolvedType::Array(inner, _) => {
            if let ResolvedType::Array(arg_inner, _) = arg_type {
                unify(inner, arg_inner, bindings);
            }
        }
        ResolvedType::Tuple(items) => {
            if let ResolvedType::Tuple(arg_items) = arg_type {
                for (param, arg) in items.iter().zip(arg_items.iter()) {
                    unify(param, arg, bindings);
                }
            }
        }
        _ => {}
    }
}

fn infer_type_args(ctx: &MonoContext, generic_func: &TypedFunction, arg_types: &[ResolvedType]) -> Result<Vec<ResolvedType>, KainError> {
    let mut bindings: std::collections::HashMap<String, ResolvedType> = std::collections::HashMap::new();
    let param_types: Vec<ResolvedType> = match &generic_func.resolved_type {
        ResolvedType::Function { params, .. } => params.clone(),
        _ => generic_func.ast.params.iter().map(|param| resolve_ast_type(&param.ty).unwrap_or(ResolvedType::Unknown)).collect(),
    };
    for (param_ty, arg_ty) in param_types.iter().zip(arg_types.iter()) {
        unify(param_ty, arg_ty, &mut bindings);
    }
    let mut inferred = Vec::new();
    for generic in &generic_func.ast.generics {
        let ty = bindings.get(&generic.name).cloned().unwrap_or(ResolvedType::Unknown);
        for bound in &generic.bounds {
            let type_name = type_to_string(&ty);
            if !ctx.trait_impls.contains(&(bound.trait_name.clone(), type_name.clone())) {
                return Err(KainError::type_error(format!("Type '{}' does not satisfy bound '{}'", type_name, bound.trait_name), generic.span));
            }
        }
        inferred.push(ty);
    }
    Ok(inferred)
}

fn substitute_type(ty: &ResolvedType, mapping: &std::collections::HashMap<String, ResolvedType>) -> ResolvedType {
    match ty {
        ResolvedType::Generic(name) => mapping.get(name).cloned().unwrap_or_else(|| ty.clone()),
        ResolvedType::Function { params, ret, effects } => ResolvedType::Function {
            params: params.iter().map(|param| substitute_type(param, mapping)).collect(),
            ret: Box::new(substitute_type(ret, mapping)),
            effects: effects.clone(),
        },
        ResolvedType::Array(inner, n) => ResolvedType::Array(Box::new(substitute_type(inner, mapping)), *n),
        ResolvedType::Struct(name, fields) => ResolvedType::Struct(name.clone(), fields.iter().map(|(k, v)| (k.clone(), substitute_type(v, mapping))).collect()),
        ResolvedType::Tuple(items) => ResolvedType::Tuple(items.iter().map(|item| substitute_type(item, mapping)).collect()),
        ResolvedType::Option(inner) => ResolvedType::Option(Box::new(substitute_type(inner, mapping))),
        ResolvedType::Result(ok, err) => ResolvedType::Result(Box::new(substitute_type(ok, mapping)), Box::new(substitute_type(err, mapping))),
        ResolvedType::Ref { mutable, inner } => ResolvedType::Ref { mutable: *mutable, inner: Box::new(substitute_type(inner, mapping)) },
        ResolvedType::Ptr { mutable, inner } => ResolvedType::Ptr { mutable: *mutable, inner: Box::new(substitute_type(inner, mapping)) },
        ResolvedType::Slice(inner) => ResolvedType::Slice(Box::new(substitute_type(inner, mapping))),
        _ => ty.clone(),
    }
}

impl MonoTypeEnv {
    fn define(&mut self, name: String, ty: ResolvedType) {
        if let Some(scope) = self.scopes.last_mut() {
            scope.insert(name, ty);
        }
    }
}

fn lower_async_fn(_ctx: &mut MonoContext, func: &TypedFunction) -> Result<TypedFunction, KainError> {
    let mut entry_fn = func.clone();
    entry_fn.effects.effects.remove(&Effect::Async_);
    entry_fn.ast.effects.retain(|effect| *effect != Effect::Async_);
    Ok(entry_fn)
}

fn split_at_awaits(block: &Block, await_points: &[AwaitPoint]) -> Vec<CodeSegment> {
    let mut segments = Vec::new();
    let mut current_stmts = Vec::new();
    let mut await_idx: usize = 0;
    for stmt in &block.stmts {
        let contains_await = matches!(stmt, Stmt::Let { value: Some(Expr::Await(_, _)), .. } | Stmt::Expr(Expr::Await(_, _)) | Stmt::Return(Some(Expr::Await(_, _)), _));
        if contains_await && await_idx < await_points.len() {
            let ends_with_return = matches!(stmt, Stmt::Return(_, _));
            segments.push(CodeSegment {
                stmts_before: current_stmts.clone(),
                await_point: Some(await_points[await_idx].clone()),
                ends_with_return,
            });
            current_stmts.clear();
            await_idx += 1;
        } else {
            current_stmts.push(stmt.clone());
        }
    }
    if !current_stmts.is_empty() || segments.is_empty() {
        let ends_with_return = matches!(current_stmts.last(), Some(Stmt::Return(_, _)));
        segments.push(CodeSegment {
            stmts_before: current_stmts,
            await_point: None,
            ends_with_return,
        });
    }
    segments
}

fn generate_state_arm(state_idx: usize, segment: &CodeSegment, _await_points: &[AwaitPoint], fields: &std::collections::HashMap<String, ResolvedType>, _state_machine_name: &String, span: Span) -> MatchArm {
    let mut body_stmts = Vec::new();
    for stmt in &segment.stmts_before {
        let mut rewritten_stmt = stmt.clone();
        rewrite_stmt(&mut rewritten_stmt, fields);
        body_stmts.push(rewritten_stmt);
    }
    match &segment.await_point {
        Some(await_point) => {
            let store_field = format!("_await_{}", await_point.index);
            let mut awaited_expr = await_point.awaited_expr.clone();
            rewrite_expr(&mut awaited_expr, fields);
            body_stmts.push(Stmt::Expr(Expr::Assign {
                target: Box::new(Expr::Field {
                    object: Box::new(Expr::Ident("self".to_string(), span.clone())),
                    field: store_field,
                    span: span.clone(),
                }),
                value: Box::new(awaited_expr),
                span: span.clone(),
            }));
            body_stmts.push(Stmt::Return(
                Some(Expr::EnumVariant {
                    enum_name: "Poll".to_string(),
                    variant: "Pending".to_string(),
                    fields: EnumVariantFields::Unit,
                    span: span.clone(),
                }),
                span.clone(),
            ));
        }
        None => {
            body_stmts.push(Stmt::Return(
                Some(Expr::EnumVariant {
                    enum_name: "Poll".to_string(),
                    variant: "Ready".to_string(),
                    fields: EnumVariantFields::Tuple(vec![Expr::None(span.clone())]),
                    span: span.clone(),
                }),
                span.clone(),
            ));
        }
    }
    MatchArm {
        pattern: Pattern::Literal(Expr::Int(state_idx as i64, span.clone())),
        guard: None,
        body: Expr::Block(Block { stmts: body_stmts, span: span.clone() }, span.clone()),
        span,
    }
}

fn scan_function(_ctx: &mut MonoContext, func: &TypedFunction) -> Result<TypedFunction, KainError> {
    Ok(func.clone())
}

fn scan_block(_ctx: &mut MonoContext, env: &mut MonoTypeEnv, block: &mut Block) -> Result<(), KainError> {
    env.push();
    for stmt in &mut block.stmts {
        scan_stmt(_ctx, env, stmt)?;
    }
    env.pop();
    Ok(())
}

fn scan_stmt(ctx: &mut MonoContext, env: &mut MonoTypeEnv, stmt: &mut Stmt) -> Result<(), KainError> {
    match stmt {
        Stmt::Expr(expr) => {
            let _ = scan_expr(ctx, env, expr)?;
        }
        Stmt::Return(Some(expr), _) => {
            let _ = scan_expr(ctx, env, expr)?;
        }
        Stmt::Let { pattern, value, .. } => {
            if let Some(expr) = value {
                let ty = scan_expr(ctx, env, expr)?;
                if let Pattern::Binding { name, .. } = pattern {
                    env.define(name.clone(), ty);
                }
            }
        }
        Stmt::For { binding, iter, body, .. } => {
            let iter_ty = scan_expr(ctx, env, iter)?;
            let elem_ty = match iter_ty {
                ResolvedType::Array(inner, _) => *inner,
                _ => ResolvedType::Unknown,
            };
            env.push();
            if let Pattern::Binding { name, .. } = binding {
                env.define(name.clone(), elem_ty);
            }
            scan_block(ctx, env, body)?;
            env.pop();
        }
        Stmt::While { condition, body, .. } => {
            let _ = scan_expr(ctx, env, condition)?;
            scan_block(ctx, env, body)?;
        }
        Stmt::Loop { body, .. } => {
            scan_block(ctx, env, body)?;
        }
        _ => {}
    }
    Ok(())
}

fn scan_expr(_ctx: &mut MonoContext, env: &mut MonoTypeEnv, expr: &mut Expr) -> Result<ResolvedType, KainError> {
    match expr {
        Expr::Int(_, _) => Ok(ResolvedType::Int(IntSize::I64)),
        Expr::Float(_, _) => Ok(ResolvedType::Float(FloatSize::F64)),
        Expr::String(_, _) => Ok(ResolvedType::String),
        Expr::Bool(_, _) => Ok(ResolvedType::Bool),
        Expr::None(_) => Ok(ResolvedType::Unknown),
        Expr::Ident(name, _) => Ok(env.get(name)),
        Expr::Unary { op, operand, .. } => {
            let operand_ty = scan_expr(_ctx, env, operand)?;
            match op {
                UnaryOp::Neg => Ok(operand_ty),
                UnaryOp::Not | UnaryOp::BitNot => Ok(ResolvedType::Bool),
                UnaryOp::Ref => Ok(ResolvedType::Ref { mutable: false, inner: Box::new(operand_ty) }),
                UnaryOp::RefMut => Ok(ResolvedType::Ref { mutable: true, inner: Box::new(operand_ty) }),
                UnaryOp::Deref => match operand_ty {
                    ResolvedType::Ref { inner, .. } => Ok(*inner),
                    _ => Ok(operand_ty),
                },
            }
        }
        Expr::Struct { name, .. } => Ok(ResolvedType::Struct(name.clone(), std::collections::HashMap::new())),
        Expr::Field { object, field, .. } => {
            let obj_ty = scan_expr(_ctx, env, object)?;
            match obj_ty {
                ResolvedType::Struct(name, _) => Ok(env.get(&format!("{}_{}", name, field)).clone()),
                _ => Ok(ResolvedType::Unknown),
            }
        }
        Expr::MethodCall { receiver, args, .. } => {
            let _ = scan_expr(_ctx, env, receiver)?;
            for arg in args {
                let _ = scan_expr(_ctx, env, &mut arg.value)?;
            }
            Ok(ResolvedType::Unknown)
        }
        Expr::Call { callee, args, .. } => {
            let _ = scan_expr(_ctx, env, callee)?;
            for arg in args {
                let _ = scan_expr(_ctx, env, &mut arg.value)?;
            }
            Ok(ResolvedType::Unknown)
        }
        Expr::Binary { left, right, .. } => {
            let left_ty = scan_expr(_ctx, env, left)?;
            let _ = scan_expr(_ctx, env, right)?;
            Ok(left_ty)
        }
        Expr::Assign { value, .. } => scan_expr(_ctx, env, value),
        Expr::Block(block, _) => {
            scan_block(_ctx, env, block)?;
            Ok(ResolvedType::Unknown)
        }
        Expr::If { condition, then_branch, else_branch, .. } => {
            let _ = scan_expr(_ctx, env, condition)?;
            scan_block(_ctx, env, then_branch)?;
            if let Some(branch) = else_branch {
                match branch.as_mut() {
                    ElseBranch::Else(block) => scan_block(_ctx, env, block)?,
                    ElseBranch::ElseIf(_, block, _) => scan_block(_ctx, env, block)?,
                }
            }
            Ok(ResolvedType::Unknown)
        }
        Expr::Await(inner, _) => scan_expr(_ctx, env, inner),
        Expr::Array(_, _) | Expr::Tuple(_, _) | Expr::Match { .. } | Expr::EnumVariant { .. } | Expr::AggregateInit { .. } | Expr::JSX(_, _) => Ok(ResolvedType::Unknown),
        _ => Ok(ResolvedType::Unknown),
    }
}

fn render_to_string(node: &VNode) -> String {
    match node {
        VNode::Element { tag, attrs, children, .. } => {
            let rendered_attrs: Vec<String> = attrs.iter().map(render_attr_to_string).filter(|s| !s.is_empty()).collect();
            let attr_suffix = if rendered_attrs.is_empty() { String::new() } else { format!(" {}", rendered_attrs.join(" ")) };
            if children.is_empty() {
                format!("<{}{} />", tag, attr_suffix)
            } else {
                let rendered_children: Vec<String> = children.iter().map(render_to_string).collect();
                format!("<{}{}>{}</{}>", tag, attr_suffix, rendered_children.join(""), tag)
            }
        }
        VNode::Text(text) => text.clone(),
        VNode::Fragment(children) => children.iter().map(render_to_string).collect::<Vec<_>>().join(""),
        VNode::Component { rendered, .. } => render_to_string(rendered),
    }
}

fn eval_jsx(env: &mut Env, node: &JSXNode) -> Result<Value, KainError> {
    match node {
        JSXNode::Element { tag, attributes, children, .. } => {
            let attrs = eval_attrs(env, attributes)?;
            let children = eval_children(env, children)?;
            let key = find_attr_key(&attrs, &"key".to_string());
            Ok(Value::JSX(VNode::Element { tag: tag.clone(), attrs, children, key }))
        }
        JSXNode::Text(s, _) => Ok(Value::String(s.clone())),
        JSXNode::Expression(expr) => eval_expr(env, expr),
        JSXNode::Fragment(children, _) => Ok(Value::JSX(VNode::Fragment(eval_children(env, children)?))),
        JSXNode::If { condition, then_branch, else_branch, .. } => {
            let cond = eval_expr(env, condition)?;
            if value_is_truthy(&cond) {
                eval_jsx(env, then_branch)
            } else {
                match else_branch {
                    Some(else_branch) => eval_jsx(env, else_branch),
                    None => Ok(Value::JSX(VNode::Fragment(Vec::new()))),
                }
            }
        }
        JSXNode::For { iter, body, .. } => {
            let iter_value = eval_expr(env, iter)?;
            let items = match iter_value {
                Value::Array(items) => items.read().unwrap().clone(),
                Value::Tuple(items) => items,
                _ => Vec::new(),
            };
            let mut children = Vec::new();
            for _item in items {
                let rendered = eval_jsx(env, body)?;
                flatten_value_into_children(rendered, &mut children);
            }
            Ok(Value::JSX(VNode::Fragment(children)))
        }
        JSXNode::ComponentCall { name, props, children, .. } => {
            let attrs = eval_attrs(env, props)?;
            let rendered_children = eval_children(env, children)?;
            let props = attrs_to_props_map(&attrs);
            let instance = ComponentInstance { name: name.clone(), props, children: rendered_children.clone(), state_: std::collections::HashMap::new() };
            Ok(Value::JSX(VNode::Component { instance, rendered: Box::new(VNode::Fragment(rendered_children)) }))
        }
    }
}

fn eval_attrs(env: &mut Env, attributes: &[JSXAttribute]) -> Result<Vec<UIAttr>, KainError> {
    let mut attrs = Vec::new();
    for attr in attributes {
        let lowered = match &attr.value {
            JSXAttrValue::String(s) => UIAttr::Property { name: attr.name.clone(), value: Value::String(s.clone()) },
            JSXAttrValue::Bool(b) => UIAttr::Bool { name: attr.name.clone(), value: *b },
            JSXAttrValue::Expr(expr) => {
                let value = eval_expr(env, expr)?;
                match parse_event_name(&attr.name) {
                    Some(event) => UIAttr::Event { name: attr.name.clone(), event, handler: value },
                    None => UIAttr::Property { name: attr.name.clone(), value },
                }
            }
        };
        attrs.push(lowered);
    }
    Ok(attrs)
}

fn eval_children(env: &mut Env, children: &[JSXNode]) -> Result<Vec<VNode>, KainError> {
    let mut out_ = Vec::new();
    for child in children {
        let rendered = eval_jsx(env, child)?;
        flatten_value_into_children(rendered, &mut out_);
    }
    Ok(out_)
}

fn flatten_value_into_children(value: Value, out_: &mut Vec<VNode>) {
    match value {
        Value::JSX(node) => out_.push(node),
        Value::String(s) => out_.push(VNode::Text(s)),
        Value::Int(n) => out_.push(VNode::Text(n.to_string())),
        Value::Float(n) => out_.push(VNode::Text(n.to_string())),
        Value::Bool(b) => out_.push(VNode::Text(b.to_string())),
        Value::Array(items) => {
            for item in items.read().unwrap().iter().cloned() {
                flatten_value_into_children(item, out_)
            }
        }
        Value::Tuple(items) => {
            for item in items {
                flatten_value_into_children(item, out_)
            }
        }
        _ => {}
    }
}

fn attrs_to_props_map(attrs: &[UIAttr]) -> std::collections::HashMap<String, Value> {
    let mut props = std::collections::HashMap::new();
    for attr in attrs {
        match attr {
            UIAttr::Property { name, value, .. } => { let _ = props.insert(name.clone(), value.clone()); }
            UIAttr::Bool { name, value, .. } => { let _ = props.insert(name.clone(), Value::Bool(*value)); }
            UIAttr::Event { name, handler, .. } => { let _ = props.insert(name.clone(), handler.clone()); }
        }
    }
    props
}

fn render_attr_to_string(attr: &UIAttr) -> String {
    match attr {
        UIAttr::Property { name, value, .. } => format!("{}=\"{}\"", name, value),
        UIAttr::Bool { name, value, .. } => if *value { name.clone() } else { String::new() },
        UIAttr::Event { name, event, .. } => format!("{}=\"[event:{}]\"", name, event_name(event)),
    }
}

fn parse_event_name(name: &String) -> Option<UIEvent> {
    let normalized = name.strip_prefix("on_").unwrap_or(name).to_ascii_lowercase();
    match normalized.as_str() {
        "click" => Some(UIEvent::Click),
        "input" => Some(UIEvent::Input),
        "change" => Some(UIEvent::Change),
        "submit" => Some(UIEvent::Submit),
        "focus" => Some(UIEvent::Focus),
        "blur" => Some(UIEvent::Blur),
        "keydown" => Some(UIEvent::KeyDown),
        "keyup" => Some(UIEvent::KeyUp),
        "pointerdown" => Some(UIEvent::PointerDown),
        "pointerup" => Some(UIEvent::PointerUp),
        "pointermove" => Some(UIEvent::PointerMove),
        _ => None,
    }
}

fn event_name(event: &UIEvent) -> String {
    match event {
        UIEvent::Click => "click".to_string(),
        UIEvent::Input => "input".to_string(),
        UIEvent::Change => "change".to_string(),
        UIEvent::Submit => "submit".to_string(),
        UIEvent::Focus => "focus".to_string(),
        UIEvent::Blur => "blur".to_string(),
        UIEvent::KeyDown => "keydown".to_string(),
        UIEvent::KeyUp => "keyup".to_string(),
        UIEvent::PointerDown => "pointerdown".to_string(),
        UIEvent::PointerUp => "pointerup".to_string(),
        UIEvent::PointerMove => "pointermove".to_string(),
        UIEvent::Custom(name) => name.clone(),
    }
}

fn value_is_truthy(value: &Value) -> bool {
    match value {
        Value::Unit | Value::None => false,
        Value::Bool(v) => *v,
        Value::Int(v) => *v != 0,
        Value::Float(v) => *v != 0.0,
        Value::String(v) => !v.is_empty(),
        Value::Array(items) => !items.read().unwrap().is_empty(),
        Value::Tuple(items) => !items.is_empty(),
        Value::JSX(_) => true,
        _ => true,
    }
}

fn find_attr_key(attrs: &[UIAttr], name: &String) -> Option<String> {
    for attr in attrs {
        match attr {
            UIAttr::Property { name: attr_name, value, .. } if attr_name == name => return Some(value_to_key_string(value)),
            UIAttr::Bool { name: attr_name, value, .. } if attr_name == name => return Some(value.to_string()),
            _ => {}
        }
    }
    None
}

fn value_to_key_string(value: &Value) -> String {
    match value {
        Value::String(v) => v.clone(),
        Value::Int(v) => v.to_string(),
        Value::Float(v) => v.to_string(),
        Value::Bool(v) => v.to_string(),
        _ => value.to_string(),
    }
}

impl VNode {
    fn fmt_impl(&self, f: &mut Formatter<'_>) -> Result<(), KainError> {
        f.write_str(&render_to_string(self)).map_err(|e| KainError::Runtime(e.to_string(), Span::new(0, 0)))
    }
}

impl Value {
    fn fmt_impl(&self, f: &mut Formatter<'_>) -> Result<(), KainError> {
        f.write_str(&self.to_string()).map_err(|e| KainError::Runtime(e.to_string(), Span::new(0, 0)))
    }
}

impl std::fmt::Display for ErrorKind {
    fn fmt(&self, f: &mut Formatter<'_>) -> std::fmt::Result {
        f.write_str(&format!("{:?}", self))
    }
}

impl std::fmt::Display for VNode {
    fn fmt(&self, f: &mut Formatter<'_>) -> std::fmt::Result {
        self.fmt_impl(f).map_err(|_| std::fmt::Error)
    }
}

impl std::fmt::Display for Value {
    fn fmt(&self, f: &mut Formatter<'_>) -> std::fmt::Result {
        self.fmt_impl(f).map_err(|_| std::fmt::Error)
    }
}

fn spec_for_code(code: DiagnosticCode) -> DiagnosticSpec {
    match code {
        DiagnosticCode::UnexpectedToken => DiagnosticSpec { code, severity: DiagnosticSeverity::Error, message: "Unexpected token".to_string() },
        _ => DiagnosticSpec { code, severity: DiagnosticSeverity::Error, message: format!("{:?}", code) },
    }
}

impl LanguageCapabilities {
    fn with_override(mut self, capability: LanguageCapability, enabled: bool) -> LanguageCapabilities {
        self.flags.insert(capability, enabled);
        self
