fn eval_program(program: &mut Program) -> Result<(), KainError> {
    let mut env = Env::new();
    for item in &mut program.items {
        eval_item(&mut env, item)?;
    }
    Ok(())
}

fn eval_item(env: &mut Env, item: &mut Item) -> Result<(), KainError> {
    match item {
        Item::Function(f) => eval_block(env, &mut f.body)?,
        Item::Comptime(block) => eval_block(env, &mut block.body)?,
        Item::Component(c) => {
            eval_jsx(env, &mut c.body)?;
            for method in &mut c.methods {
                eval_block(env, &mut method.body)?;
            }
        }
        Item::Const(c) => eval_expr_in_place(env, &mut c.value)?,
        _ => ()
    }
    Ok(())
}

