#[derive(Debug, Clone, PartialEq)]
struct SpanMapper {
    pub source: String,
    pub line_starts: Vec<usize>,
}

impl SpanMapper {
    fn new(source: &String) -> SpanMapper {
        let mut line_starts = vec![0];
        for (idx, ch) in source.char_indices() {
            if ch == '\\n' {
                line_starts.push(idx + 1);
            }
        }
        SpanMapper { source: source.clone(), line_starts }
    }

    fn span_to_location(&self, span: Span, file: &String) -> SourceLocation {
        if self.line_starts.is_empty() {
            return SourceLocation::new(file, 1, 1);
        }
        let start = span.start.min(self.source.len());
        let line_idx = match self.line_starts.binary_search(&start) {
            Ok(idx) => idx,
            Err(idx) => idx.saturating_sub(1),
        };
        let line_start = self.line_starts[line_idx];
        let col = start.saturating_sub(line_start) + 1;
        SourceLocation::new(file, line_idx + 1, col)
    }

    fn source(&self) -> String {
        self.source.clone()
    }
}

#[derive(Debug, Clone, PartialEq)]
struct Diagnostics {
    pub source: String,
    pub filename: String,
}

impl Diagnostics {
    fn new(source: &String, filename: &String) -> Diagnostics {
        Diagnostics { source: source.clone(), filename: filename.clone() }
    }

    fn format_error(&self, error: &KainError) -> String {
        match error {
            KainError::Lexer { message, span, .. } => self.format_with_context(&"Lexer Error".to_string(), message, span.clone()),
            KainError::Parser { message, span, .. } => self.format_with_context(&"Parse Error".to_string(), message, span.clone()),
            KainError::Type { message, span, .. } => self.format_with_context(&"Type Error".to_string(), message, span.clone()),
            KainError::Effect { message, span, .. } => self.format_with_context(&"Effect Error".to_string(), message, span.clone()),
            KainError::Borrow { message, span, .. } => self.format_with_context(&"Borrow Error".to_string(), message, span.clone()),
            KainError::Codegen { message, span, .. } => self.format_with_context(&"Codegen Error".to_string(), message, span.clone()),
            KainError::CodegenWithLocation { message, file, line_, col, .. } => format!("\nerror[Codegen]: {}\n  --> {}:{}:{}\n", message, file, line_, col),
            KainError::Runtime { message, .. } => format!("\nerror: {}\n", message),
            KainError::Io(e) => format!("\nerror: IO error: {:?}\n", e),
            KainError::Enhanced { .. } => format!("\n{:?}\n", error),
            KainError::Multi(errors) => {
                let mut output = format!("\nerror: {} error(s) found:\n", errors.len());
                for (i, err) in errors.iter().enumerate() {
                    output.push_str(&format!("\n--- [{}/{}] ---\n", i + 1, errors.len()));
                    output.push_str(&self.format_error(err));
                }
                output
            }
        }
    }

    fn format_with_context(&self, error_type: &String, message: &String, span: Span) -> String {
        let (line_num, col, line_content) = self.get_line_info(span);
        format!("\nerror[{}]: {}\n  --> {}:{}:{}\n{:>3} | {}\n", error_type, message, self.filename, line_num, col, line_num, line_content)
    }

    fn get_line_info(&self, span: Span) -> (usize, usize, String) {
        let start = span.start.min(self.source.len());
        let mut line_num = 1usize;
        let mut line_start = 0usize;
        for (idx, ch) in self.source.char_indices() {
            if idx >= start {
                break;
            }
            if ch == '\\n' {
                line_num += 1;
                line_start = idx + 1;
            }
        }
        let col = start.saturating_sub(line_start) + 1;
        let line_end = self.source[line_start..].find('\\n').map(|offset| line_start + offset).unwrap_or(self.source.len());
        let line_content = self.source[line_start..line_end].to_string();
        (line_num, col, line_content)
    }
}

