fn format_enhanced_error(kind: &ErrorKind, code: &DiagnosticCode, file: &Option<std::path::PathBuf>, location: &Option<(usize, usize)>, context: &String, message: &String, suggestion: &Option<String>) -> String {
    let spec = spec_for_code(*code);
    let mut output = String::new();
    output.push_str(&format!("❌ [{}:{}] {}", kind, spec.code_str, spec.title));
    if let Some(path) = file {
        output.push_str(&format!(" in {}", path.display()));
        if let Some((line_, col)) = location {
            output.push_str(&format!(":{}:{}", line_, col));
        }
    }
    output.push_str("\n\n");
    if !context.is_empty() {
        output.push_str(&format!("   Context: {}\n", context));
    }
    output.push_str(&format!("   {}\n", message));
    if let Some(help_text) = suggestion.as_deref().or(spec.default_suggestion.as_deref()) {
        output.push_str(&format!("\n   Help: {}\n", help_text));
    }
    if let Some(docs_key) = spec.docs_key.as_deref() {
        output.push_str(&format!("\n   Reference: {}\n", docs_key));
    }
    output
}

