fn render_to_string(node: &VNode) -> String {
    match node {
        VNode::Element { tag, attrs, children, .. } => {
            let rendered_attrs: Vec<String> = attrs.iter().map(render_attr_to_string).filter(|s| !s.is_empty()).collect();
            let attr_suffix = if rendered_attrs.is_empty() { String::new() } else { format!(" {}", rendered_attrs.join(" ")) };
            if children.is_empty() {
                format!("<{}{} />", tag, attr_suffix)
            } else {
                let rendered_children: Vec<String> = children.iter().map(render_to_string).collect();
                format!("<{}{}>{}</{}>", tag, attr_suffix, rendered_children.join(""), tag)
            }
        }
        VNode::Text(text) => text.clone(),
        VNode::Fragment(children) => children.iter().map(render_to_string).collect::<Vec<_>>().join(""),
        VNode::Component { rendered, .. } => render_to_string(rendered),
    }
}

fn eval_jsx(env: &mut Env, node: &JSXNode) -> Result<Value, KainError> {
    match node {
        JSXNode::Element { tag, attributes, children, .. } => {
            let attrs = eval_attrs(env, attributes)?;
            let children = eval_children(env, children)?;
            let key = find_attr_key(&attrs, &"key".to_string());
            Ok(Value::JSX(VNode::Element { tag: tag.clone(), attrs, children, key }))
        }
        JSXNode::Text(s, _) => Ok(Value::String(s.clone())),
        JSXNode::Expression(expr) => eval_expr(env, expr),
        JSXNode::Fragment(children, _) => Ok(Value::JSX(VNode::Fragment(eval_children(env, children)?))),
        JSXNode::If { condition, then_branch, else_branch, .. } => {
            let cond = eval_expr(env, condition)?;
            if value_is_truthy(&cond) {
                eval_jsx(env, then_branch)
            } else {
                match else_branch {
                    Some(else_branch) => eval_jsx(env, else_branch),
                    None => Ok(Value::JSX(VNode::Fragment(Vec::new()))),
                }
            }
        }
        JSXNode::For { iter, body, .. } => {
            let iter_value = eval_expr(env, iter)?;
            let items = match iter_value {
                Value::Array(items) => items.read().unwrap().clone(),
                Value::Tuple(items) => items,
                _ => Vec::new(),
            };
            let mut children = Vec::new();
            for _item in items {
                let rendered = eval_jsx(env, body)?;
                flatten_value_into_children(rendered, &mut children);
            }
            Ok(Value::JSX(VNode::Fragment(children)))
        }
        JSXNode::ComponentCall { name, props, children, .. } => {
            let attrs = eval_attrs(env, props)?;
            let rendered_children = eval_children(env, children)?;
            let props = attrs_to_props_map(&attrs);
            let instance = ComponentInstance {
                name: name.clone(),
                props,
                children: rendered_children.clone(),
                state_: std::collections::HashMap::new(),
            };
            Ok(Value::JSX(VNode::Component {
                instance,
                rendered: Box::new(VNode::Fragment(rendered_children)),
            }))
        }
    }
}

fn eval_attrs(env: &mut Env, attributes: &[JSXAttribute]) -> Result<Vec<UIAttr>, KainError> {
    let mut attrs = Vec::new();
    for attr in attributes {
        let lowered = match &attr.value {
            JSXAttrValue::String(s) => UIAttr::Property { name: attr.name.clone(), value: Value::String(s.clone()) },
            JSXAttrValue::Bool(b) => UIAttr::Bool { name: attr.name.clone(), value: *b },
            JSXAttrValue::Expr(expr) => {
                let value = eval_expr(env, expr)?;
                match parse_event_name(&attr.name) {
                    Some(event) => UIAttr::Event { name: attr.name.clone(), event, handler: value },
                    None => UIAttr::Property { name: attr.name.clone(), value },
                }
            }
        };
        attrs.push(lowered);
    }
    Ok(attrs)
}

fn eval_children(env: &mut Env, children: &[JSXNode]) -> Result<Vec<VNode>, KainError> {
    let mut out_ = Vec::new();
    for child in children {
        let rendered = eval_jsx(env, child)?;
        flatten_value_into_children(rendered, &mut out_);
    }
    Ok(out_)
}

fn flatten_value_into_children(value: Value, out_: &mut Vec<VNode>) {
    match value {
        Value::JSX(node) => out_.push(node),
        Value::String(s) => out_.push(VNode::Text(s)),
        Value::Int(n) => out_.push(VNode::Text(n.to_string())),
        Value::Float(n) => out_.push(VNode::Text(n.to_string())),
        Value::Bool(b) => out_.push(VNode::Text(b.to_string())),
        Value::Array(items) => {
            for item in items.read().unwrap().iter().cloned() {
                flatten_value_into_children(item, out_)
            }
        }
        Value::Tuple(items) => {
            for item in items {
                flatten_value_into_children(item, out_)
            }
        }
        _ => {}
    }
}

fn attrs_to_props_map(attrs: &[UIAttr]) -> std::collections::HashMap<String, Value> {
    let mut props = std::collections::HashMap::new();
    for attr in attrs {
        match attr {
            UIAttr::Property { name, value, .. } => { let _ = props.insert(name.clone(), value.clone()); }
            UIAttr::Bool { name, value, .. } => { let _ = props.insert(name.clone(), Value::Bool(*value)); }
            UIAttr::Event { name, handler, .. } => { let _ = props.insert(name.clone(), handler.clone()); }
        }
    }
    props
}

fn render_attr_to_string(attr: &UIAttr) -> String {
    match attr {
        UIAttr::Property { name, value, .. } => format!("{}=\"{}\"", name, value),
        UIAttr::Bool { name, value, .. } => if *value { name.clone() } else { String::new() },
        UIAttr::Event { name, event, .. } => format!("{}=\"[event:{}]\"", name, event_name(event)),
    }
}

fn parse_event_name(name: &String) -> Option<UIEvent> {
    let normalized = name.strip_prefix("on_").unwrap_or(name).to_ascii_lowercase();
    match normalized.as_str() {
        "click" => Some(UIEvent::Click),
        "input" => Some(UIEvent::Input),
        "change" => Some(UIEvent::Change),
        "submit" => Some(UIEvent::Submit),
        "focus" => Some(UIEvent::Focus),
        "blur" => Some(UIEvent::Blur),
        "keydown" => Some(UIEvent::KeyDown),
        "keyup" => Some(UIEvent::KeyUp),
        "pointerdown" => Some(UIEvent::PointerDown),
        "pointerup" => Some(UIEvent::PointerUp),
        "pointermove" => Some(UIEvent::PointerMove),
        _ => None,
    }
}

fn event_name(event: &UIEvent) -> String {
    match event {
        UIEvent::Click => "click".to_string(),
        UIEvent::Input => "input".to_string(),
        UIEvent::Change => "change".to_string(),
        UIEvent::Submit => "submit".to_string(),
        UIEvent::Focus => "focus".to_string(),
        UIEvent::Blur => "blur".to_string(),
        UIEvent::KeyDown => "keydown".to_string(),
        UIEvent::KeyUp => "keyup".to_string(),
        UIEvent::PointerDown => "pointerdown".to_string(),
        UIEvent::PointerUp => "pointerup".to_string(),
        UIEvent::PointerMove => "pointermove".to_string(),
        UIEvent::Custom(name) => name.clone(),
    }
}

fn value_is_truthy(value: &Value) -> bool {
    match value {
        Value::Unit | Value::None => false,
        Value::Bool(v) => *v,
        Value::Int(v) => *v != 0,
        Value::Float(v) => *v != 0.0,
        Value::String(v) => !v.is_empty(),
        Value::Array(items) => !items.read().unwrap().is_empty(),
        Value::Tuple(items) => !items.is_empty(),
        Value::JSX(_) => true,
        _ => true,
    }
}

fn find_attr_key(attrs: &[UIAttr], name: &String) -> Option<String> {
    for attr in attrs {
        match attr {
            UIAttr::Property { name: attr_name, value, .. } if attr_name == name => return Some(value_to_key_string(value)),
            UIAttr::Bool { name: attr_name, value, .. } if attr_name == name => return Some(value.to_string()),
            _ => {}
        }
    }
    None
}

fn value_to_key_string(value: &Value) -> String {
    match value {
        Value::String(v) => v.clone(),
        Value::Int(v) => v.to_string(),
        Value::Float(v) => v.to_string(),
        Value::Bool(v) => v.to_string(),
        _ => value.to_string(),
    }
}

