fn collect_from_pattern(pattern: &Pattern, locals: &mut std::collections::HashMap<String, ResolvedType>) {
    match pattern {
        Pattern::Binding { name, .. } => {
            let _ = locals.insert(name.clone(), ResolvedType::Unknown);
        }
        Pattern::Tuple(pats, _) => {
            for p in pats {
                collect_from_pattern(p, locals);
            }
        }
        Pattern::Slice { patterns, rest, .. } => {
            for p in patterns {
                collect_from_pattern(p, locals);
            }
            if let Some(r) = rest {
                let _ = locals.insert(r.clone(), ResolvedType::Unknown);
            }
        }
        Pattern::Struct { fields, .. } => {
            for (_, p) in fields {
                collect_from_pattern(p, locals);
            }
        }
        Pattern::Variant { fields, .. } => match fields {
            VariantPatternFields::Tuple(pats) => {
                for p in pats {
                    collect_from_pattern(p, locals);
                }
            }
            VariantPatternFields::Struct(pats) => {
                for (_, p) in pats {
                    collect_from_pattern(p, locals);
                }
            }
            _ => {}
        },
        Pattern::Or(pats, _) => {
            for p in pats {
                collect_from_pattern(p, locals);
            }
        }
        _ => {}
    }
}

