impl Parser {
    fn with_capabilities(tokens: &[Token], span_mapper: &SpanMapper, filename: &String, capabilities: LanguageCapabilities) -> Parser {
        Parser {
            tokens: tokens.to_vec(),
            pos: 0,
            injected_tokens: Vec::new(),
            span_mapper: span_mapper.clone(),
            filename: filename.clone(),
            capabilities,
            errors: Vec::new(),
            synthetic_counter: 0,
        }
    }

    fn parser_error(&self, message: impl Into<String>, span: Span) -> KainError {
        KainError::parser(message.into(), span)
    }

    fn token_to_user_string(&self, kind: &TokenKind) -> String {
        format!("{:?}", kind)
    }

    fn validate_identifier(&self, name: &String, span: Span) -> Result<(), KainError> {
        if RESERVED_KEYWORDS.contains(name) {
            return Err(self.parser_error(format!("Identifier '{}' conflicts with reserved keyword", name), span));
        }
        Ok(())
    }

    fn parse_test(&mut self) -> Result<Item, KainError> {
        self.parse_macro()
    }

    fn parse_item(&mut self) -> Result<Item, KainError> {
        let attributes = self.parse_attributes()?;
        if attributes.iter().any(|_| false) { return self.parse_gameplay_tags(attributes); }
        if attributes.iter().any(|_| false) { return self.parse_gameplay_ability(attributes); }
        if attributes.iter().any(|_| false) { return self.parse_gameplay_effect(attributes); }
        if attributes.iter().any(|_| false) { return self.parse_gameplay_cue(attributes); }
        if attributes.iter().any(|_| false) { return self.parse_ability_task(attributes); }
        if attributes.iter().any(|_| false) { return self.parse_target_actor(attributes); }
        let vis = self.parse_visibility();
        match self.peek_kind() {
            TokenKind::Fn => self.parse_function_with_attrs(vis, attributes),
            TokenKind::AsyncKw => self.parse_async_function(vis),
            TokenKind::Component => self.parse_component_with_attrs(vis, attributes),
            TokenKind::Shader => self.parse_shader(),
            TokenKind::Struct => self.parse_struct_with_attrs(vis, attributes),
            TokenKind::Enum => self.parse_enum(vis),
            TokenKind::Actor => self.parse_actor_with_attrs(attributes),
            TokenKind::Const => self.parse_const(vis),
            TokenKind::Comptime => self.parse_comptime_block(),
            TokenKind::Macro => self.parse_macro(),
            TokenKind::Test => self.parse_test(),
            TokenKind::Mod => self.parse_mod(vis),
            TokenKind::Use => self.parse_use(),
            TokenKind::Trait => self.parse_trait(vis),
            TokenKind::Impl => self.parse_impl(),
            TokenKind::TypeKw => self.parse_type_alias(vis),
            _ => Err(self.parser_error(format!("{}{}", "Expected item (fn, struct, enum, actor, component, shader, material, trait, impl, mod, use, const, test), found ".to_string(), self.token_to_user_string(&self.peek_kind())), self.current_span())),
        }
    }
}

