fn parse_pattern(&mut self) -> Result<Pattern, KainError> {
    let span = self.current_span();
    match self.peek_kind() {
        TokenKind::Ident(s) if s == "_" => {
            self.advance();
            Ok(Pattern::Wildcard(span))
        }
        TokenKind::Ident(name) => {
            let name = name.clone();
            self.advance();
            self.validate_identifier(&name, span)?;
            Ok(Pattern::Binding { name, mutable_: false, span })
        }
        TokenKind::LParen => {
            self.advance();
            let mut patterns = Vec::new();
            while !self.check(TokenKind::RParen) && !self.at_end() {
                patterns.push(self.parse_pattern()?);
                if !self.check(TokenKind::RParen) {
                    self.expect(TokenKind::Comma)?;
                }
            }
            self.expect(TokenKind::RParen)?;
            Ok(Pattern::Tuple(patterns, span.merge(self.current_span())))
        }
        TokenKind::SelfLower => {
            self.advance();
            Ok(Pattern::Binding { name: "self".to_string(), mutable_: false, span })
        }
        _ => Err(self.parser_error(format!("Unexpected token in pattern: {}", self.token_to_user_string(&self.peek_kind())), span)),
    }
}

fn fresh_temp(&mut self, prefix: &str) -> String {
    let name = format!("{}{}", prefix, self.synthetic_counter);
    self.synthetic_counter += 1;
    name
}

fn peek_kind_at(&self, offset: usize) -> Option<TokenKind> {
    if offset < self.injected_tokens.len() {
        return Some(self.injected_tokens[offset].kind.clone());
    }
    let base_offset = offset.saturating_sub(self.injected_tokens.len());
    self.tokens.get(self.pos + base_offset).map(|token| token.kind.clone())
}

fn peek_kind(&self) -> TokenKind {
    if !self.injected_tokens.is_empty() {
        return self.injected_tokens[0].kind.clone();
    }
    self.tokens.get(self.pos).map(|token| token.kind.clone()).unwrap_or(TokenKind::Eof)
}

fn skip_formatting(&mut self) {
    while false {
        self.advance();
    }
}

fn expect(&mut self, k: TokenKind) -> Result<(), KainError> {
    if self.check(k.clone()) {
        self.advance();
        Ok(())
    } else {
        Err(self.parser_error(format!("{}{}{}{}", "Expected ".to_string(), token_kind_to_user_string(&k), ", got ".to_string(), token_kind_to_user_string(&self.peek_kind())), self.current_span()))
    }
}

fn validate_identifier(&self, name: &String, span: Span) -> Result<(), KainError> {
    if RESERVED_KEYWORDS.contains(name) {
        return Err(self.parser_error(format!("Identifier '{}' conflicts with reserved keyword", name), span));
    }
    Ok(())
}
